#include <Arduino.h>
#include <Servo.h>
Servo servo1, servo2, servo3;

void setup();
void loop();
void resetSystem();
void setup() {
  pinMode(2, OUTPUT);  
  pinMode(3, OUTPUT);  
  pinMode(4, OUTPUT);  
  for (int i = 8; i <= 13; i++) pinMode(i, OUTPUT);
  pinMode(44, OUTPUT);
  pinMode(45, OUTPUT);
  servo1.attach(5);
  servo2.attach(6);
  servo3.attach(7);
  resetSystem();
  delay(2000);
}
void loop() {
  servo1.write(60);
  digitalWrite(2, HIGH);
  digitalWrite(8, HIGH);
  digitalWrite(9, HIGH);
  delay(2000);
  servo2.write(120);
  digitalWrite(3, HIGH);
  digitalWrite(10, HIGH);
  digitalWrite(11, HIGH);
  digitalWrite(12, HIGH);
  delay(2000);
  servo3.write(180);
  digitalWrite(4, HIGH);
  digitalWrite(13, HIGH);
  digitalWrite(44, HIGH);
  digitalWrite(45, HIGH);
  delay(2000);
  resetSystem();
  delay(2000);
}
void resetSystem() {
  digitalWrite(2, LOW);
  digitalWrite(3, LOW);
  digitalWrite(4, LOW);
  servo1.write(0);
  servo2.write(0);
  servo3.write(0);
  for (int i = 8; i <= 13; i++) digitalWrite(i, LOW);
  digitalWrite(44, LOW);
  digitalWrite(45, LOW);
}
